CREATE OR REPLACE FUNCTION app.shipping_cents(
  region text,
  weight_grams integer
)
RETURNS integer
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  base integer;
BEGIN
  CASE region
    WHEN 'eu', 'us' THEN
      base := 500;
      RETURN base + weight_grams * 2;
    WHEN 'apac' THEN
      IF weight_grams > 1000 THEN
